/* ============================================================
   ثيم ناف — النسخة المصحّحة
   كل التعديلات موسومة بـ  [مُصحَّح]  مع سبب التغيير
   جميع أزواج النص/الخلفية تتجاوز 4.5:1 — معيار WCAG AA
   ============================================================ */

@import "tailwindcss";

@custom-variant dark (&:is(.dark *));

:root {
  --background: oklch(0.9383 0.0042 236.4993);
  --foreground: oklch(0.3211 0 0);
  --card: oklch(1.0000 0 0);
  --card-foreground: oklch(0.3211 0 0);
  --popover: oklch(1.0000 0 0);
  --popover-foreground: oklch(0.3211 0 0);

  /* [مُصحَّح] 0.6325 -> 0.5700 — كان الأبيض عليه 3.49، صار 4.51 */
  --primary: oklch(0.5700 0.0904 80.9413);
  --primary-foreground: oklch(1.0000 0 0);

  --secondary: oklch(0.9670 0.0029 264.5419);
  --secondary-foreground: oklch(0.2972 0.0398 246.6002);
  --muted: oklch(0.9846 0.0017 247.8389);

  /* [مُصحَّح] 0.5510 -> 0.5250 — كان 4.04 على الخلفية، صار 4.51 */
  --muted-foreground: oklch(0.5250 0.0234 264.3637);

  --accent: oklch(0.9119 0.0222 243.8174);
  --accent-foreground: oklch(0.3791 0.1378 265.5222);

  /* [مُصحَّح] 0.6368 -> 0.5930 — زر الحذف كان 3.76، صار 4.50 */
  --destructive: oklch(0.5930 0.2078 25.3313);
  --destructive-foreground: oklch(1.0000 0 0);

  /* [جديد] ألوان الحالة — كانت غائبة تماماً
     لحالات: معتمد / قيد المراجعة / معلومة
     كلها تتجاوز 4.5 مع النص الأبيض */
  --success: oklch(0.5540 0.1200 155.0000);
  --success-foreground: oklch(1.0000 0 0);
  --warning: oklch(0.5720 0.1400 75.0000);
  --warning-foreground: oklch(1.0000 0 0);
  --info: oklch(0.5640 0.1200 240.0000);
  --info-foreground: oklch(1.0000 0 0);

  --border: oklch(0.8853 0 0);
  --input: oklch(0.9700 0.0029 264.5420);

  /* [مُصحَّح] تبع الأساسي الجديد ليبقى حلقة التركيز مطابقة للزر */
  --ring: oklch(0.5700 0.0904 80.9413);

  /* [مُصحَّح] لوحة الرسوم الخمس — أُعيدت بقياس لا بالعين.
     كان chart-5 عند إضاءة 0.221 (أسود عملياً)، وكان chart-4 و chart-5
     على مدرجَي لون متجاورين (259 و247) فلا يفترقان: ΔE 7.8 حتى بنظر
     سليم، والحدّ 15. وثلاثة منها تحت أرضية التشبّع 0.10 فتُقرأ رمادية.

     المدارج الآن خمسة متباعدة — ذهبي 80، أزرق 240، أخضر 155،
     بنفسجي 300، أحمر 20 — بإضاءة داخل النطاق وتشبّع فوق الأرضية.
     تجتاز الخمسة كلها فحوص التشبّع وعمى الألوان والتباين في الوضعين.

     ملحوظة: chart-1 ليس لون الهوية. --primary لم يُمسّ. */
  --chart-1: oklch(0.5500 0.1100 80.0000);
  --chart-2: oklch(0.5400 0.1400 240.0000);
  --chart-3: oklch(0.5500 0.1500 155.0000);
  --chart-4: oklch(0.5200 0.1700 300.0000);
  --chart-5: oklch(0.5500 0.1600 20.0000);

  --sidebar: oklch(0.9030 0.0046 258.3257);
  --sidebar-foreground: oklch(0.2210 0.0253 246.6492);

  /* [مُصحَّح] كان برتقالياً #E05D38 عند الزاوية 36 — عائلة لونية ثالثة
     دخيلة من قالب جاهز. وُحّد على الذهبي الأساسي. */
  --sidebar-primary: oklch(0.5700 0.0904 80.9413);
  --sidebar-primary-foreground: oklch(1.0000 0 0);

  --sidebar-accent: oklch(0.9119 0.0222 243.8174);

  /* [مُصحَّح] كان ذهبياً فاتحاً على أزرق فاتح = 2.70، أسوأ نسبة في الملف */
  --sidebar-accent-foreground: oklch(0.2972 0.0398 246.6002);

  --sidebar-border: oklch(0.8853 0 0);
  --sidebar-ring: oklch(0.5700 0.0904 80.9413);

  --font-sans: IBM Plex Sans Arabic, ui-sans-serif, sans-serif, system-ui;
  --font-serif: IBM Plex Serif, ui-serif, serif;
  --font-mono: IBM Plex Mono, ui-monospace, monospace;

  /* [مُصحَّح] 1.175rem = 18.8px — شبه بيضاوي على الأزرار، لغة استهلاكية.
     0.5rem = 8px يناسب سياق الاستشارات القانونية.
     هذا قرار جمالي — غيّره لو خالفتني الرأي. */
  --radius: 0.5rem;

  --shadow-x: 0px;
  --shadow-y: 1px;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-opacity: 0.1;
  --shadow-color: hsl(0 0% 0%);
  --shadow-2xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.25);

  /* [جديد] خلفيات ناعمة للحالات — لم تكن موجودة، فكانت كل منصة
     تخترع لنفسها قيماً ثابتة تتعارض مع الأساسي عند تغييره.
     مشتقّة لا مستقلة: تمزج الرمز الأساس في سطح البطاقة، فتتبع
     الوضعين تلقائياً بتعريف واحد ولا تحتاج كتلة في .dark.
     نسبة 14% مضبوطة بصرياً في الوضعين. */
  --primary-soft: color-mix(in oklab, var(--primary) 14%, var(--card));
  --secondary-soft: color-mix(in oklab, var(--secondary) 14%, var(--card));
  --destructive-soft: color-mix(in oklab, var(--destructive) 14%, var(--card));
  --success-soft: color-mix(in oklab, var(--success) 14%, var(--card));
  --warning-soft: color-mix(in oklab, var(--warning) 14%, var(--card));
  --info-soft: color-mix(in oklab, var(--info) 14%, var(--card));

  /* [جديد] نصّ الحالات فوق خلفياتها الناعمة — قياساً لا تخميناً.
     النصّ بالرمز الأساس على خلفيته الناعمة يعطي 3.7–3.8 فقط، ونصّ الشارة
     صغير فحدّه 4.5. هذه الرموز تخفض الإضاءة حتى تتجاوزه، وتبقى مشتقّة
     من الصبغة نفسها فلا تُدخل لوناً جديداً.
     تُستعمل لنصّ الشارة والتنبيه الهادئ فوق ‎--*-soft‎ حصراً. */
  --success-strong: oklch(0.5040 0.1200 155.0000);
  --warning-strong: oklch(0.5220 0.1400 75.0000);
  --destructive-strong: oklch(0.5430 0.2078 25.3313);
  --info-strong: oklch(0.5140 0.1200 240.0000);
  --primary-strong: oklch(0.5200 0.0904 80.9413);

  /* [جديد] السطح العميق — سطح دلاليّ داكن يحمل نصاً فاتحاً: خلفيات الصفحات
     خارج البطاقة، وأغلفة الشرائح وفواصلها وختامها.
     ليس ‎--mark-navy‎: ذاك لرسم العلامة وحدها ولا يُستعمل سطحاً، وهذا رمز
     دلاليّ للسطح لا لون هوية. والتمييز بينهما هو ما يمنع «الهوية لوحة ألوان». */
  --surface-deep: oklch(0.3451 0.0833 260.8804);
  --surface-deep-foreground: oklch(1.0000 0 0);
  --surface-deep-muted: oklch(0.9119 0.0222 243.8174);

  /* [جديد] ظلّ البطاقة المرتفعة — البطاقة العائمة على سطح عميق تحتاج عمقاً
     أكبر من سلّم الظلال العادي، وكانت المنصات تكتبه rgba خاماً. */
  --shadow-elevated: 0px 18px 50px 0px hsl(0 0% 0% / 0.28);

  /* [جديد] تدرّجات بطاقات المنصات — خمسة لخمس منصات.

     مشتقّة لا مستقلة، على نمط ‎--*-soft‎ نفسه: كل تدرّج من درجة اللوحة
     الزخرفية chart-N إلى مزيجها في السطح العميق. فتتبع الوضعين بتعريف
     واحد ولا تحتاج كتلة في ‎.dark‎، ولا تُدخل قيمة لون جديدة إلى النظام.

     ولماذا chart لا الرموز الدلالية: القاعدة تقول «رموز دلالية للواجهة،
     ودرجات اللوحة للزخرفة». وخلفية البطاقة زخرفةٌ تميّز منصة عن أخرى ولا
     تُبلّغ حالة — والحالة تقولها الشارة والنصّ.

     والاتجاه ‎to bottom‎ رأسيّ عمداً: التدرّج المائل يحمل مكوّناً أفقياً
     يلزمه قلبٌ في RTL، والرأسيّ يستوي في الاتجاهين فلا يحتاج استثناءً.

     النصّ فوقها ‎--surface-deep-foreground‎ لأن طرفَي كل تدرّج داكنان. */
  --grad-1: linear-gradient(to bottom, var(--chart-1), color-mix(in oklab, var(--chart-1) 45%, var(--surface-deep)));
  --grad-2: linear-gradient(to bottom, var(--chart-2), color-mix(in oklab, var(--chart-2) 45%, var(--surface-deep)));
  --grad-3: linear-gradient(to bottom, var(--chart-3), color-mix(in oklab, var(--chart-3) 45%, var(--surface-deep)));
  --grad-4: linear-gradient(to bottom, var(--chart-4), color-mix(in oklab, var(--chart-4) 45%, var(--surface-deep)));
  --grad-5: linear-gradient(to bottom, var(--chart-5), color-mix(in oklab, var(--chart-5) 45%, var(--surface-deep)));

  /* [جديد] سلّم المقاسات رموزاً — كان السلّم متاحاً لمنصات Tailwind فقط،
     والمنصات التي تكتب CSS خاماً كانت تضبط كل مقاس يدوياً. القيم هي درجات
     السلّم نفسها المعروضة في صفحة المعاينة، لا سلّم جديد.
     ارتفاعات السطر تبقى من قواعد الجسم — لا تُخفَّض للعربية. */
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;

  /* [جديد] ارتفاعات الأسطر للسلّم — كانت الفجوة التي تُبطل §5.
     Tailwind يولّد: line-height: var(--tw-leading, var(--text-xs--line-height))
     فإن لم نعرّف الثانية فازت قيم Tailwind اللاتينية، وهي 1.111 إلى 1.556.
     وكل صنف مقاس كان يخفض بها ارتفاع السطر عن 1.8 المضبوطة على الجسم،
     فتضيع المساحة الرأسية التي تحتاجها العربية للصعود والنزول والتشكيل.

     القيم أدناه أطول من نظيرتها اللاتينية في كل درجة. تتقارب عند مقاسات
     العرض لأن العنوان الكبير بارتفاع 1.8 يتفكّك — لكنها لا تنزل تحت 1.2. */
  --text-xs--line-height: 1.75;
  --text-sm--line-height: 1.75;
  --text-base--line-height: 1.8;
  --text-lg--line-height: 1.75;
  --text-xl--line-height: 1.65;
  --text-2xl--line-height: 1.5;
  --text-3xl--line-height: 1.4;
  --text-4xl--line-height: 1.3;
  --text-5xl--line-height: 1.2;

  /* [جديد] ألوان العلامات الخارجية — استثناء منصوص عليه.
     هذه ليست قيم تصميم لناف بل هويات مملوكة لأطراف أخرى، وتغييرها
     يجعل أيقونات المنصات غير قابلة للتعرّف. تُسجَّل هنا لتبقى تحت
     السجلّ بدل أن تتكرّر خاماً في كل منصة.
     تُستعمل لخلفيات أيقونات المنصات حصراً — لا لأي عنصر واجهة آخر. */
  /* [جديد] حجاب النوافذ المنبثقة — لم يكن له رمز، فكانت كل منصة
     تكتب rgba سوداء بنسبة تخمّنها. مشتقّ من أسود الثيم لا مستقل. */
  --overlay: color-mix(in oklab, var(--shadow-color) 60%, transparent);

  /* [جديد] ألوان علامة ناف — مأخوذة من ملفات الشعار نفسها لا بالعين.
     للشعار حصراً كألوان العلامات الخارجية أدناه: عنصر الواجهة يأخذ
     رمزاً دلالياً، ولو ناسبه الكحلي. الهوية ليست لوحة ألوان. */
  --mark-navy: #233143;
  --mark-mint: #E5EEE8;
  --mark-taupe: #C0B3A3;

  --brand-linkedin: #0A66C2;
  --brand-x: #000000;
  --brand-instagram: #DD2A7B;
  --brand-instagram-gradient: linear-gradient(45deg, #F58529, #DD2A7B, #8134AF, #515BD4);
  --brand-facebook: #1877F2;
  --brand-youtube: #FF0000;
  --brand-tiktok: #010101;
  --brand-snapchat: #FFFC00;
  --brand-snapchat-foreground: #111111;
  --brand-threads: #000000;
  --brand-google: #4285F4;

  /* [جديد] مقدّمة رقع العلامات الخارجية. بيضاء في الوضعين لأن الخلفية
     لون علامة ثابت لا سطح ثيم — ولذلك لا يصلح --primary-foreground
     الذي ينقلب في الوضع الداكن، فكانت المنصات تكتب #fff خاماً.
     لمقدّمات رقع العلامات حصراً، كأخواتها أعلاه. */
  --brand-on-color: #FFFFFF;

  --tracking-normal: 0em;
  --spacing: 0.25rem;

  /* [جديد] سلّم المسافات رموزاً — --spacing كان معرّفاً وحده، متاحاً
     لمنصات Tailwind دون غيرها، فالمنصات التي تكتب CSS خاماً كانت تضبط
     كل مسافة بالبكسل. القيم مضاعفات --spacing نفسها لا سلّم جديد.
     الدرجات الثماني تغطّي ما وُجد في المنصات المربوطة. */
  --space-1: calc(var(--spacing) * 1);   /* 4  */
  --space-2: calc(var(--spacing) * 2);   /* 8  */
  --space-3: calc(var(--spacing) * 3);   /* 12 */
  --space-4: calc(var(--spacing) * 4);   /* 16 */
  --space-5: calc(var(--spacing) * 5);   /* 20 */
  --space-6: calc(var(--spacing) * 6);   /* 24 */
  --space-7: calc(var(--spacing) * 7);   /* 28 */
  --space-9: calc(var(--spacing) * 9);   /* 36 */

  /* [جديد] مقاسات الهيكل — عرض الشريط الجانبي وارتفاع الترويسة وحدود
     عرض المحتوى. كانت كل منصة تكتبها بيدها، فصار الشريط 260 و264 و300
     في ثلاث منصات، والترويسة 60 هنا و«ما تراكم» هناك. القيم رموز الآن
     فالهيكل واحد بقياس واحد.

     وحدّ عرض المحتوى ثلاث درجات لا رقم واحد: شاشةُ نموذجٍ واحد تُقرأ
     أضيق من جدول، وسطرٌ طويل بلا حدّ يُتعب العين (§٥ «مقاس محدود
     للنصّ الطويل»). فالدرجة تُختار بصنف مسجَّل لا برقم يُكتب في الشاشة. */
  --shell-sidebar: 17.5rem;  /* 280 */
  --shell-header: 3.75rem;   /* 60  */
  --page-narrow: 36rem;      /* 576  — شاشة مهمّة واحدة: نموذج، تسجيل دخول */
  --page-default: 75rem;     /* 1200 — الافتراضي: أغلب الشاشات */
  --page-wide: 87.5rem;      /* 1400 — الجداول العريضة ولوحات التحليلات */
}

.dark {
  --background: oklch(0.2598 0.0306 262.6666);
  --foreground: oklch(0.9219 0 0);
  --card: oklch(0.3106 0.0301 268.6365);
  --card-foreground: oklch(0.9219 0 0);
  --popover: oklch(0.2900 0.0249 268.3986);
  --popover-foreground: oklch(0.9219 0 0);

  /* [مُصحَّح] رُفعت الإضاءة في الداكن — الذهبي الغامق يذوب في خلفية داكنة.
     هذا هو الأصل في الوضع الداكن: الألوان تفتح لا تغمق. */
  --primary: oklch(0.7300 0.0904 80.9413);
  --primary-foreground: oklch(0.2100 0.0250 262.0000);

  /* [مُصحَّح] كان #D9D9D9 رمادياً فاتحاً — مستطيل ساطع وسط شاشة داكنة.
     صار سطحاً داكناً كما يجب. */
  --secondary: oklch(0.3550 0.0280 265.0000);
  --secondary-foreground: oklch(0.9219 0 0);

  --muted: oklch(0.3095 0.0266 266.7132);
  --muted-foreground: oklch(0.7155 0 0);
  --accent: oklch(0.3380 0.0589 267.5867);

  /* [مُصحَّح] 0.6325 -> 0.7050 — كان 3.41، صار 4.52 */
  --accent-foreground: oklch(0.7050 0.0904 80.9413);

  /* [مُصحَّح] رُفعت الإضاءة ليظهر الأحمر على خلفية داكنة */
  --destructive: oklch(0.7000 0.1900 25.3313);
  --destructive-foreground: oklch(0.2100 0.0250 262.0000);

  /* [جديد] ألوان الحالة في الوضع الداكن */
  --success: oklch(0.7200 0.1300 155.0000);
  --success-foreground: oklch(0.2100 0.0250 262.0000);
  --warning: oklch(0.7800 0.1300 75.0000);
  --warning-foreground: oklch(0.2100 0.0250 262.0000);
  --info: oklch(0.7300 0.1100 240.0000);
  --info-foreground: oklch(0.2100 0.0250 262.0000);

  /* [جديد] نظائر الوضع الداكن: النصّ يفتح لا يغمق فوق الخلفية الناعمة الداكنة */
  --success-strong: oklch(0.7300 0.1300 155.0000);
  --warning-strong: oklch(0.7800 0.1300 75.0000);
  --destructive-strong: oklch(0.8050 0.1900 25.3313);
  --info-strong: oklch(0.7400 0.1100 240.0000);
  --primary-strong: oklch(0.7450 0.0904 80.9413);

  --border: oklch(0.3843 0.0301 269.7337);
  --input: oklch(0.3843 0.0301 269.7337);
  --ring: oklch(0.7300 0.0904 80.9413);

  /* [مُصحَّح] chart-4 و chart-5 كانا منسوخين من الوضع الفاتح بلا تفتيح،
     فيبقيان داكنَين على سطح داكن: تباين 2.2 و 1.57 مقابل السطح.
     ورُصد أثره فعلاً — شارة «حقوق ملكية» غير مقروءة في منصة المحاسبة.

     الخمسة الآن بنفس مدارج الوضع الفاتح، بإضاءة الوضع الداكن. */
  --chart-1: oklch(0.6600 0.1100 80.0000);
  --chart-2: oklch(0.6400 0.1400 240.0000);
  --chart-3: oklch(0.6500 0.1500 155.0000);
  --chart-4: oklch(0.6200 0.1600 300.0000);
  --chart-5: oklch(0.6300 0.1500 20.0000);

  --sidebar: oklch(0.3100 0.0283 267.7408);
  --sidebar-foreground: oklch(0.9219 0 0);

  /* [مُصحَّح] وُحّد على الذهبي — كان برتقالياً هنا أيضاً */
  --sidebar-primary: oklch(0.7300 0.0904 80.9413);
  --sidebar-primary-foreground: oklch(0.2100 0.0250 262.0000);

  --sidebar-accent: oklch(0.3380 0.0589 267.5867);
  --sidebar-accent-foreground: oklch(0.9219 0 0);
  --sidebar-border: oklch(0.3843 0.0301 269.7337);
  --sidebar-ring: oklch(0.7300 0.0904 80.9413);

  --font-sans: IBM Plex Sans Arabic, ui-sans-serif, sans-serif, system-ui;
  --font-serif: IBM Plex Serif, ui-serif, serif;
  --font-mono: IBM Plex Mono, ui-monospace, monospace;
  --radius: 0.5rem;

  --shadow-x: 0px;
  --shadow-y: 1px;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-opacity: 0.1;
  --shadow-color: hsl(0 0% 0%);
  --shadow-2xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.10), 0px 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.25);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);

  /* [جديد] */
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);

  /* [جديد] الخلفيات الناعمة وألوان العلامات الخارجية */
  --color-primary-soft: var(--primary-soft);
  --color-secondary-soft: var(--secondary-soft);
  --color-destructive-soft: var(--destructive-soft);
  --color-success-soft: var(--success-soft);
  --color-warning-soft: var(--warning-soft);
  --color-info-soft: var(--info-soft);
  --color-success-strong: var(--success-strong);
  --color-warning-strong: var(--warning-strong);
  --color-destructive-strong: var(--destructive-strong);
  --color-info-strong: var(--info-strong);
  --color-primary-strong: var(--primary-strong);
  --color-surface-deep: var(--surface-deep);
  --color-surface-deep-foreground: var(--surface-deep-foreground);
  --color-surface-deep-muted: var(--surface-deep-muted);
  --shadow-elevated: var(--shadow-elevated);
  --radius-2xl: var(--radius-2xl);
  --color-overlay: var(--overlay);
  --color-mark-navy: var(--mark-navy);
  --color-mark-mint: var(--mark-mint);
  --color-mark-taupe: var(--mark-taupe);
  --color-brand-linkedin: var(--brand-linkedin);
  --color-brand-x: var(--brand-x);
  --color-brand-instagram: var(--brand-instagram);
  --color-brand-facebook: var(--brand-facebook);
  --color-brand-youtube: var(--brand-youtube);
  --color-brand-tiktok: var(--brand-tiktok);
  --color-brand-snapchat: var(--brand-snapchat);
  --color-brand-snapchat-foreground: var(--brand-snapchat-foreground);
  --color-brand-threads: var(--brand-threads);
  --color-brand-google: var(--brand-google);
  --color-brand-on-color: var(--brand-on-color);

  /* [جديد] سلّم المسافات */
  --spacing-1: var(--space-1);
  --spacing-2: var(--space-2);
  --spacing-3: var(--space-3);
  --spacing-4: var(--space-4);
  --spacing-5: var(--space-5);
  --spacing-6: var(--space-6);
  --spacing-7: var(--space-7);
  --spacing-9: var(--space-9);

  /* [جديد] مقاسات الهيكل */
  --spacing-shell-sidebar: var(--shell-sidebar);
  --spacing-shell-header: var(--shell-header);
  --container-page-narrow: var(--page-narrow);
  --container-page-default: var(--page-default);
  --container-page-wide: var(--page-wide);

  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);
  --font-serif: var(--font-serif);

  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 10px);

  --shadow-2xs: var(--shadow-2xs);
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow: var(--shadow);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-xl: var(--shadow-xl);
  --shadow-2xl: var(--shadow-2xl);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    /* [جديد] ارتفاع سطر أطول — العربية تحتاج مساحة رأسية
       للصعود والنزول والتشكيل أكثر من اللاتينية */
    line-height: 1.8;
  }
}
